/* ============================================================================
Merchant Sales-Based Financing Strategy Simulator
Module 2.8 — Servicing Execution Simulation, Payment Processing
             & Account Lifecycle Control

Program     : 191_msbf_m2_8_servicing_payment_lifecycle_validation_v0_2.sql
Version     : v0.2

Purpose
-------
Execute 120 substantive positive controls across lifecycle, accepted M2.7
identity, dictionaries, source and execution grain, payment sequence and
amounts, window-function cumulative evidence, lifecycle transitions,
non-production boundaries, latest/archive reproduction, stress
non-improvement, hashes, canonical identity, and readiness.

Stage boundary
--------------
All servicing, payment, processor-reference, return, retry, and lifecycle
outputs are deterministic synthetic evidence. No real funds move; no bank or
routing data is used; no ACH/network transmission, external processor call,
merchant contact, write-off/collection/legal execution, external notice, or
production adverse action occurs.

Required result
---------------
120 / 120 PASS and run_status=M2_8_VALIDATED.
============================================================================ */

BEGIN;SET LOCAL work_mem='160MB';SET LOCAL statement_timeout='50min';SET LOCAL jit=off;
DROP TABLE IF EXISTS _m28_validation;CREATE TEMP TABLE _m28_validation(evidence_code text PRIMARY KEY,metric_name text,observed_value text,threshold_value text,status text,interpretation text) ON COMMIT PRESERVE ROWS;
CREATE TEMP TABLE _m28_vctx ON COMMIT DROP AS SELECT run_id,run_status FROM msbf_ctl.run_registry WHERE run_code='M1_V0_2_BASELINE_BUILD' AND run_version=1;
DO $ready$ BEGIN PERFORM msbf_ctl.m2_8_assert_validation_ready((SELECT run_id FROM _m28_vctx));END;$ready$;
CREATE OR REPLACE FUNCTION pg_temp.m2_8_add_check(p_code text,p_metric text,p_observed text,p_threshold text,p_pass boolean,p_interpretation text) RETURNS void LANGUAGE plpgsql AS $function$ BEGIN INSERT INTO _m28_validation VALUES(p_code,p_metric,p_observed,p_threshold,CASE WHEN p_pass THEN 'PASS' ELSE 'FAIL' END,p_interpretation);END;$function$;
DO $checks$ BEGIN
    PERFORM pg_temp.m2_8_add_check('M2_8_POS_001_RUN_STATUS','RUN_STATUS',((SELECT run_status FROM _m28_vctx))::text,'M2_8_GENERATED|M2_8_VALIDATED',coalesce(((SELECT run_status IN ('M2_8_GENERATED','M2_8_VALIDATED') FROM _m28_vctx)),FALSE),'Run lifecycle is generated or validated.');
    PERFORM pg_temp.m2_8_add_check('M2_8_POS_002_CONTRACT_STATUS','CONTRACT_STATUS',((SELECT contract_status FROM msbf_ctl.m2_8_servicing_execution_contract_registry WHERE module1_run_id=(SELECT run_id FROM _m28_vctx)))::text,'GENERATED|VALIDATED',coalesce(((SELECT contract_status IN ('GENERATED','VALIDATED') FROM msbf_ctl.m2_8_servicing_execution_contract_registry WHERE module1_run_id=(SELECT run_id FROM _m28_vctx))),FALSE),'Contract lifecycle aligns with validation.');
    PERFORM pg_temp.m2_8_add_check('M2_8_POS_003_POLICY_STATUS','POLICY_STATUS',((SELECT policy_status FROM msbf_ctl.m2_8_policy_profile WHERE module1_run_id=(SELECT run_id FROM _m28_vctx)))::text,'APPROVED',coalesce(((SELECT policy_status='APPROVED' FROM msbf_ctl.m2_8_policy_profile WHERE module1_run_id=(SELECT run_id FROM _m28_vctx))),FALSE),'Policy is approved.');
    PERFORM pg_temp.m2_8_add_check('M2_8_POS_004_METHOD_IDENTITY','METHOD_IDENTITY',((SELECT methodology_version||'|'||contract_code||'|'||contract_version::text||'|'||schema_version FROM msbf_ctl.m2_8_policy_profile WHERE module1_run_id=(SELECT run_id FROM _m28_vctx)))::text,'M2_8_METHOD_V1|M2_SERVICING_EXECUTION_PAYMENT_LIFECYCLE_CONSUMPTION|1|M2_8_SERVICING_EXECUTION_PAYMENT_LIFECYCLE_SCHEMA_V1',coalesce(((SELECT methodology_version='M2_8_METHOD_V1' AND contract_code='M2_SERVICING_EXECUTION_PAYMENT_LIFECYCLE_CONSUMPTION' AND contract_version=1 AND schema_version='M2_8_SERVICING_EXECUTION_PAYMENT_LIFECYCLE_SCHEMA_V1' FROM msbf_ctl.m2_8_policy_profile WHERE module1_run_id=(SELECT run_id FROM _m28_vctx))),FALSE),'Methodology and contract identity are exact.');
    PERFORM pg_temp.m2_8_add_check('M2_8_POS_005_SOURCE_IDENTITY','SOURCE_IDENTITY',((SELECT source_contract_code||'|'||source_schema_version||'|'||source_combined_set_hash FROM msbf_ctl.m2_8_policy_profile WHERE module1_run_id=(SELECT run_id FROM _m28_vctx)))::text,'M2_OPERATIONAL_ACTIVATION_ACCOUNT_SETUP_CONSUMPTION|M2_7_OPERATIONAL_ACTIVATION_ACCOUNT_SETUP_SCHEMA_V1|c8e3a472afd2a16b1183677324e9db98',coalesce(((SELECT source_contract_code='M2_OPERATIONAL_ACTIVATION_ACCOUNT_SETUP_CONSUMPTION' AND source_schema_version='M2_7_OPERATIONAL_ACTIVATION_ACCOUNT_SETUP_SCHEMA_V1' AND source_combined_set_hash='c8e3a472afd2a16b1183677324e9db98' FROM msbf_ctl.m2_8_policy_profile WHERE module1_run_id=(SELECT run_id FROM _m28_vctx))),FALSE),'Accepted M2.7 identity is exact.');
    PERFORM pg_temp.m2_8_add_check('M2_8_POS_006_SOURCE_REGISTRY','SOURCE_REGISTRY',((SELECT contract_status||'|'||contract_code||'|'||combined_set_hash FROM msbf_ctl.m2_7_operational_activation_contract_registry WHERE module1_run_id=(SELECT run_id FROM _m28_vctx)))::text,'ACCEPTED|M2_OPERATIONAL_ACTIVATION_ACCOUNT_SETUP_CONSUMPTION|c8e3a472afd2a16b1183677324e9db98',coalesce(((SELECT contract_status='ACCEPTED' AND contract_code='M2_OPERATIONAL_ACTIVATION_ACCOUNT_SETUP_CONSUMPTION' AND combined_set_hash='c8e3a472afd2a16b1183677324e9db98' FROM msbf_ctl.m2_7_operational_activation_contract_registry WHERE module1_run_id=(SELECT run_id FROM _m28_vctx))),FALSE),'Physical accepted M2.7 registry is exact.');
    PERFORM pg_temp.m2_8_add_check('M2_8_POS_007_SOURCE_GATE','SOURCE_GATE',((SELECT result_status FROM msbf_ctl.acceptance_gate_result WHERE run_id=(SELECT run_id FROM _m28_vctx) AND gate_id='M2_7_OPERATIONAL_ACTIVATION_ACCOUNT_SETUP' AND review_version=1))::text,'PASS',coalesce(((SELECT result_status='PASS' FROM msbf_ctl.acceptance_gate_result WHERE run_id=(SELECT run_id FROM _m28_vctx) AND gate_id='M2_7_OPERATIONAL_ACTIVATION_ACCOUNT_SETUP' AND review_version=1)),FALSE),'Accepted M2.7 gate is PASS.');
    PERFORM pg_temp.m2_8_add_check('M2_8_POS_008_CONFIG_HASH','CONFIG_HASH',((SELECT configuration_hash FROM msbf_ctl.m2_8_policy_profile WHERE module1_run_id=(SELECT run_id FROM _m28_vctx)))::text,'physical configuration hash',coalesce(((SELECT configuration_hash=msbf_ctl.m2_8_hash_jsonb(configuration_payload) FROM msbf_ctl.m2_8_policy_profile WHERE module1_run_id=(SELECT run_id FROM _m28_vctx))),FALSE),'Configuration hash reconstructs.');
    PERFORM pg_temp.m2_8_add_check('M2_8_POS_009_POLICY_HASH','POLICY_HASH_ERRORS',((SELECT count(*) FROM msbf_ctl.m2_8_policy_profile p WHERE p.module1_run_id=(SELECT run_id FROM _m28_vctx) AND p.row_hash IS DISTINCT FROM msbf_ctl.m2_8_hash_jsonb(to_jsonb(p)-'row_hash'-'created_at'-'updated_at')))::text,'0',coalesce(((SELECT count(*)=0 FROM msbf_ctl.m2_8_policy_profile p WHERE p.module1_run_id=(SELECT run_id FROM _m28_vctx) AND p.row_hash IS DISTINCT FROM msbf_ctl.m2_8_hash_jsonb(to_jsonb(p)-'row_hash'-'created_at'-'updated_at'))),FALSE),'Policy row hash reconstructs.');
    PERFORM pg_temp.m2_8_add_check('M2_8_POS_010_POLICY_BOUNDARIES','POLICY_BOUNDARIES',((SELECT synthetic_data_only_flag AND simulated_servicing_execution_only_flag AND preserve_m2_7_history_flag AND no_real_funds_movement_flag AND no_bank_account_data_flag AND no_ach_or_network_transmission_flag AND no_external_processor_call_flag AND no_real_merchant_contact_flag AND no_write_off_or_collection_execution_flag AND no_external_notice_generation_flag AND no_production_adverse_action_flag FROM msbf_ctl.m2_8_policy_profile WHERE module1_run_id=(SELECT run_id FROM _m28_vctx)))::text,'true',coalesce(((SELECT synthetic_data_only_flag AND simulated_servicing_execution_only_flag AND preserve_m2_7_history_flag AND no_real_funds_movement_flag AND no_bank_account_data_flag AND no_ach_or_network_transmission_flag AND no_external_processor_call_flag AND no_real_merchant_contact_flag AND no_write_off_or_collection_execution_flag AND no_external_notice_generation_flag AND no_production_adverse_action_flag FROM msbf_ctl.m2_8_policy_profile WHERE module1_run_id=(SELECT run_id FROM _m28_vctx))),FALSE),'All policy boundaries are enabled.');
    PERFORM pg_temp.m2_8_add_check('M2_8_POS_011_PARAMETERS','PARAMETERS',((SELECT servicing_cycle_days::text||'|'||synthetic_return_event_sequence::text||'|'||synthetic_retry_event_sequence::text||'|'||retry_catchup_multiplier::text||'|'||default_temporary_payment_factor::text||'|'||default_setup_duration_days::text||'|'||default_reassessment_interval_days::text FROM msbf_ctl.m2_8_policy_profile WHERE module1_run_id=(SELECT run_id FROM _m28_vctx)))::text,'7|4|5|2.000000|0.750000|14|7',coalesce(((SELECT servicing_cycle_days=7 AND synthetic_return_event_sequence=4 AND synthetic_retry_event_sequence=5 AND retry_catchup_multiplier=2 AND default_temporary_payment_factor=.75 AND default_setup_duration_days=14 AND default_reassessment_interval_days=7 FROM msbf_ctl.m2_8_policy_profile WHERE module1_run_id=(SELECT run_id FROM _m28_vctx))),FALSE),'Cycle parameters are exact.');
    PERFORM pg_temp.m2_8_add_check('M2_8_POS_012_GATE_CATALOG','GATE_CATALOG_ROWS',((SELECT count(*) FROM msbf_ref.acceptance_gate_catalog WHERE gate_id='M2_8_SERVICING_EXECUTION_PAYMENT_LIFECYCLE_CONTROL' AND active_flag))::text,'1',coalesce(((SELECT count(*)=1 FROM msbf_ref.acceptance_gate_catalog WHERE gate_id='M2_8_SERVICING_EXECUTION_PAYMENT_LIFECYCLE_CONTROL' AND active_flag)),FALSE),'M2.8 gate is registered.');
    PERFORM pg_temp.m2_8_add_check('M2_8_POS_013_REGISTRY_COUNT','REGISTRY_ROWS',((SELECT count(*) FROM msbf_ctl.m2_8_servicing_execution_contract_registry WHERE module1_run_id=(SELECT run_id FROM _m28_vctx)))::text,'1',coalesce(((SELECT count(*)=1 FROM msbf_ctl.m2_8_servicing_execution_contract_registry WHERE module1_run_id=(SELECT run_id FROM _m28_vctx))),FALSE),'Exactly one registry row exists.');
    PERFORM pg_temp.m2_8_add_check('M2_8_POS_014_REGISTRY_COUNTS','REGISTRY_COUNTS',((SELECT source_rows::text||'|'||execution_rows::text||'|'||payment_event_rows::text||'|'||lifecycle_transition_rows::text||'|'||latest_rows::text||'|'||archive_rows::text||'|'||comparison_rows::text||'|'||canonical_entities::text FROM msbf_ctl.m2_8_servicing_execution_contract_registry WHERE module1_run_id=(SELECT run_id FROM _m28_vctx)))::text,'59|59|7|67|59|59|15|367',coalesce(((SELECT source_rows=59 AND execution_rows=59 AND payment_event_rows=7 AND lifecycle_transition_rows=67 AND latest_rows=59 AND archive_rows=59 AND comparison_rows=15 AND canonical_entities=367 FROM msbf_ctl.m2_8_servicing_execution_contract_registry WHERE module1_run_id=(SELECT run_id FROM _m28_vctx))),FALSE),'Registry cardinalities are exact.');
    PERFORM pg_temp.m2_8_add_check('M2_8_POS_015_REGISTRY_TOTALS','REGISTRY_TOTALS',((SELECT no_processing_required_rows::text||'|'||temporary_processing_rows::text||'|'||review_hold_rows::text||'|'||settled_event_rows::text||'|'||returned_event_rows::text||'|'||retry_event_rows::text||'|'||processing_authorized_amount::text||'|'||review_hold_amount::text||'|'||processed_payment_amount::text||'|'||ending_simulated_exposure_amount::text FROM msbf_ctl.m2_8_servicing_execution_contract_registry WHERE module1_run_id=(SELECT run_id FROM _m28_vctx)))::text,'57|1|1|5|1|1|518.04|461.69|194.25|785.48',coalesce(((SELECT no_processing_required_rows=57 AND temporary_processing_rows=1 AND review_hold_rows=1 AND settled_event_rows=5 AND returned_event_rows=1 AND retry_event_rows=1 AND processing_authorized_amount=518.04 AND review_hold_amount=461.69 AND processed_payment_amount=194.25 AND ending_simulated_exposure_amount=785.48 FROM msbf_ctl.m2_8_servicing_execution_contract_registry WHERE module1_run_id=(SELECT run_id FROM _m28_vctx))),FALSE),'Registry business totals are exact.');
    PERFORM pg_temp.m2_8_add_check('M2_8_POS_016_OUTCOME_COUNT','OUTCOME_COUNT',((SELECT count(*) FROM msbf_m2.servicing_execution_outcome_definition WHERE module1_run_id=(SELECT run_id FROM _m28_vctx)))::text,'7',coalesce(((SELECT count(*)=7 FROM msbf_m2.servicing_execution_outcome_definition WHERE module1_run_id=(SELECT run_id FROM _m28_vctx))),FALSE),'OUTCOME_COUNT is exact.');
    PERFORM pg_temp.m2_8_add_check('M2_8_POS_017_ACTION_COUNT','ACTION_COUNT',((SELECT count(*) FROM msbf_m2.servicing_execution_action_definition WHERE module1_run_id=(SELECT run_id FROM _m28_vctx)))::text,'7',coalesce(((SELECT count(*)=7 FROM msbf_m2.servicing_execution_action_definition WHERE module1_run_id=(SELECT run_id FROM _m28_vctx))),FALSE),'ACTION_COUNT is exact.');
    PERFORM pg_temp.m2_8_add_check('M2_8_POS_018_STATE_COUNT','STATE_COUNT',((SELECT count(*) FROM msbf_m2.account_lifecycle_state_definition WHERE module1_run_id=(SELECT run_id FROM _m28_vctx)))::text,'7',coalesce(((SELECT count(*)=7 FROM msbf_m2.account_lifecycle_state_definition WHERE module1_run_id=(SELECT run_id FROM _m28_vctx))),FALSE),'STATE_COUNT is exact.');
    PERFORM pg_temp.m2_8_add_check('M2_8_POS_019_REASON_COUNT','REASON_COUNT',((SELECT count(*) FROM msbf_m2.servicing_execution_reason_definition WHERE module1_run_id=(SELECT run_id FROM _m28_vctx)))::text,'32',coalesce(((SELECT count(*)=32 FROM msbf_m2.servicing_execution_reason_definition WHERE module1_run_id=(SELECT run_id FROM _m28_vctx))),FALSE),'REASON_COUNT is exact.');
    PERFORM pg_temp.m2_8_add_check('M2_8_POS_020_DEFINITIONS_APPROVED','NONAPPROVED',(((SELECT count(*) FROM msbf_m2.servicing_execution_outcome_definition WHERE module1_run_id=(SELECT run_id FROM _m28_vctx) AND definition_status<>'APPROVED')+(SELECT count(*) FROM msbf_m2.servicing_execution_action_definition WHERE module1_run_id=(SELECT run_id FROM _m28_vctx) AND definition_status<>'APPROVED')+(SELECT count(*) FROM msbf_m2.account_lifecycle_state_definition WHERE module1_run_id=(SELECT run_id FROM _m28_vctx) AND definition_status<>'APPROVED')+(SELECT count(*) FROM msbf_m2.servicing_execution_reason_definition WHERE module1_run_id=(SELECT run_id FROM _m28_vctx) AND definition_status<>'APPROVED')))::text,'0',coalesce((((SELECT count(*) FROM msbf_m2.servicing_execution_outcome_definition WHERE module1_run_id=(SELECT run_id FROM _m28_vctx) AND definition_status<>'APPROVED')+(SELECT count(*) FROM msbf_m2.servicing_execution_action_definition WHERE module1_run_id=(SELECT run_id FROM _m28_vctx) AND definition_status<>'APPROVED')+(SELECT count(*) FROM msbf_m2.account_lifecycle_state_definition WHERE module1_run_id=(SELECT run_id FROM _m28_vctx) AND definition_status<>'APPROVED')+(SELECT count(*) FROM msbf_m2.servicing_execution_reason_definition WHERE module1_run_id=(SELECT run_id FROM _m28_vctx) AND definition_status<>'APPROVED')=0)),FALSE),'All definitions are approved.');
    PERFORM pg_temp.m2_8_add_check('M2_8_POS_021_OUTCOME_EXCLUSIVE','OUTCOME_EXCLUSIVE_ERRORS',((SELECT count(*) FROM msbf_m2.servicing_execution_outcome_definition WHERE module1_run_id=(SELECT run_id FROM _m28_vctx) AND num_nonnulls(NULLIF(processing_authorized_flag,FALSE),NULLIF(processing_review_required_flag,FALSE),NULLIF(no_processing_required_flag,FALSE))<>1))::text,'0',coalesce(((SELECT count(*)=0 FROM msbf_m2.servicing_execution_outcome_definition WHERE module1_run_id=(SELECT run_id FROM _m28_vctx) AND num_nonnulls(NULLIF(processing_authorized_flag,FALSE),NULLIF(processing_review_required_flag,FALSE),NULLIF(no_processing_required_flag,FALSE))<>1)),FALSE),'Outcome flags are mutually exclusive.');
    PERFORM pg_temp.m2_8_add_check('M2_8_POS_022_DEFINITION_BOUNDARY','DEFINITION_BOUNDARY_ROWS',(((SELECT count(*) FROM msbf_m2.servicing_execution_outcome_definition WHERE module1_run_id=(SELECT run_id FROM _m28_vctx) AND (real_funds_moved_flag OR bank_account_data_present_flag OR ach_or_network_transmitted_flag OR external_processor_called_flag OR merchant_contact_executed_flag OR write_off_or_collection_flag OR external_notice_generated_flag OR production_adverse_action_flag))+(SELECT count(*) FROM msbf_m2.servicing_execution_action_definition WHERE module1_run_id=(SELECT run_id FROM _m28_vctx) AND (real_funds_moved_flag OR bank_account_data_present_flag OR ach_or_network_transmitted_flag OR external_processor_called_flag OR merchant_contact_executed_flag OR write_off_or_collection_flag OR external_notice_generated_flag OR production_adverse_action_flag))+(SELECT count(*) FROM msbf_m2.account_lifecycle_state_definition WHERE module1_run_id=(SELECT run_id FROM _m28_vctx) AND (real_funds_moved_flag OR production_account_state_flag))+(SELECT count(*) FROM msbf_m2.servicing_execution_reason_definition WHERE module1_run_id=(SELECT run_id FROM _m28_vctx) AND (real_execution_reason_flag OR production_adverse_action_flag))))::text,'0',coalesce((((SELECT count(*) FROM msbf_m2.servicing_execution_outcome_definition WHERE module1_run_id=(SELECT run_id FROM _m28_vctx) AND (real_funds_moved_flag OR bank_account_data_present_flag OR ach_or_network_transmitted_flag OR external_processor_called_flag OR merchant_contact_executed_flag OR write_off_or_collection_flag OR external_notice_generated_flag OR production_adverse_action_flag))+(SELECT count(*) FROM msbf_m2.servicing_execution_action_definition WHERE module1_run_id=(SELECT run_id FROM _m28_vctx) AND (real_funds_moved_flag OR bank_account_data_present_flag OR ach_or_network_transmitted_flag OR external_processor_called_flag OR merchant_contact_executed_flag OR write_off_or_collection_flag OR external_notice_generated_flag OR production_adverse_action_flag))+(SELECT count(*) FROM msbf_m2.account_lifecycle_state_definition WHERE module1_run_id=(SELECT run_id FROM _m28_vctx) AND (real_funds_moved_flag OR production_account_state_flag))+(SELECT count(*) FROM msbf_m2.servicing_execution_reason_definition WHERE module1_run_id=(SELECT run_id FROM _m28_vctx) AND (real_execution_reason_flag OR production_adverse_action_flag))=0)),FALSE),'Definitions have no production execution flags.');
    PERFORM pg_temp.m2_8_add_check('M2_8_POS_023_OUTCOME_RANKS','OUTCOME_RANK_DUPLICATES',((SELECT count(*)-count(DISTINCT servicing_execution_outcome_rank) FROM msbf_m2.servicing_execution_outcome_definition WHERE module1_run_id=(SELECT run_id FROM _m28_vctx)))::text,'0',coalesce(((SELECT count(*)=count(DISTINCT servicing_execution_outcome_rank) FROM msbf_m2.servicing_execution_outcome_definition WHERE module1_run_id=(SELECT run_id FROM _m28_vctx))),FALSE),'Outcome ranks are unique.');
    PERFORM pg_temp.m2_8_add_check('M2_8_POS_024_ACTION_RANKS','ACTION_RANK_DUPLICATES',((SELECT count(*)-count(DISTINCT servicing_execution_action_rank) FROM msbf_m2.servicing_execution_action_definition WHERE module1_run_id=(SELECT run_id FROM _m28_vctx)))::text,'0',coalesce(((SELECT count(*)=count(DISTINCT servicing_execution_action_rank) FROM msbf_m2.servicing_execution_action_definition WHERE module1_run_id=(SELECT run_id FROM _m28_vctx))),FALSE),'Action ranks are unique.');
    PERFORM pg_temp.m2_8_add_check('M2_8_POS_025_STATE_RANKS','STATE_RANK_DUPLICATES',((SELECT count(*)-count(DISTINCT lifecycle_state_rank) FROM msbf_m2.account_lifecycle_state_definition WHERE module1_run_id=(SELECT run_id FROM _m28_vctx)))::text,'0',coalesce(((SELECT count(*)=count(DISTINCT lifecycle_state_rank) FROM msbf_m2.account_lifecycle_state_definition WHERE module1_run_id=(SELECT run_id FROM _m28_vctx))),FALSE),'State ranks are unique.');
    PERFORM pg_temp.m2_8_add_check('M2_8_POS_026_OUTCOME_HASH','OUTCOME_HASH_ERRORS',((SELECT count(*) FROM msbf_m2.servicing_execution_outcome_definition d WHERE d.module1_run_id=(SELECT run_id FROM _m28_vctx) AND d.row_hash IS DISTINCT FROM msbf_ctl.m2_8_hash_jsonb(to_jsonb(d)-'row_hash'-'created_at')))::text,'0',coalesce(((SELECT count(*)=0 FROM msbf_m2.servicing_execution_outcome_definition d WHERE d.module1_run_id=(SELECT run_id FROM _m28_vctx) AND d.row_hash IS DISTINCT FROM msbf_ctl.m2_8_hash_jsonb(to_jsonb(d)-'row_hash'-'created_at'))),FALSE),'OUTCOME_HASH reconstructs.');
    PERFORM pg_temp.m2_8_add_check('M2_8_POS_027_ACTION_HASH','ACTION_HASH_ERRORS',((SELECT count(*) FROM msbf_m2.servicing_execution_action_definition d WHERE d.module1_run_id=(SELECT run_id FROM _m28_vctx) AND d.row_hash IS DISTINCT FROM msbf_ctl.m2_8_hash_jsonb(to_jsonb(d)-'row_hash'-'created_at')))::text,'0',coalesce(((SELECT count(*)=0 FROM msbf_m2.servicing_execution_action_definition d WHERE d.module1_run_id=(SELECT run_id FROM _m28_vctx) AND d.row_hash IS DISTINCT FROM msbf_ctl.m2_8_hash_jsonb(to_jsonb(d)-'row_hash'-'created_at'))),FALSE),'ACTION_HASH reconstructs.');
    PERFORM pg_temp.m2_8_add_check('M2_8_POS_028_STATE_HASH','STATE_HASH_ERRORS',((SELECT count(*) FROM msbf_m2.account_lifecycle_state_definition d WHERE d.module1_run_id=(SELECT run_id FROM _m28_vctx) AND d.row_hash IS DISTINCT FROM msbf_ctl.m2_8_hash_jsonb(to_jsonb(d)-'row_hash'-'created_at')))::text,'0',coalesce(((SELECT count(*)=0 FROM msbf_m2.account_lifecycle_state_definition d WHERE d.module1_run_id=(SELECT run_id FROM _m28_vctx) AND d.row_hash IS DISTINCT FROM msbf_ctl.m2_8_hash_jsonb(to_jsonb(d)-'row_hash'-'created_at'))),FALSE),'STATE_HASH reconstructs.');
