    PERFORM pg_temp.m2_8_add_check('M2_8_POS_098_PORTFOLIO_TOTALS','PORTFOLIO_TOTALS',((SELECT sum(source_rows)::text||'|'||sum(processing_authorized_rows)::text||'|'||sum(review_hold_rows)::text||'|'||sum(no_processing_required_rows)::text||'|'||sum(payment_event_rows)::text||'|'||sum(lifecycle_transition_rows)::text||'|'||sum(processed_payment_amount)::text||'|'||sum(ending_simulated_exposure_amount)::text FROM msbf_m2.servicing_execution_portfolio_summary WHERE module1_run_id=(SELECT run_id FROM _m28_vctx)))::text,'59|1|1|57|7|67|194.25|785.48',coalesce(((SELECT sum(source_rows)=59 AND sum(processing_authorized_rows)=1 AND sum(review_hold_rows)=1 AND sum(no_processing_required_rows)=57 AND sum(payment_event_rows)=7 AND sum(lifecycle_transition_rows)=67 AND sum(processed_payment_amount)=194.25 AND sum(ending_simulated_exposure_amount)=785.48 FROM msbf_m2.servicing_execution_portfolio_summary WHERE module1_run_id=(SELECT run_id FROM _m28_vctx))),FALSE),'Portfolio totals reconcile.');
