    PERFORM pg_temp.m2_8_add_check('M2_8_POS_102_LATEST_IDENTITY','LATEST_IDENTITY_ERRORS',((SELECT count(*) FROM msbf_m2.application_servicing_execution_latest WHERE module1_run_id=(SELECT run_id FROM _m28_vctx) AND (contract_code<>'M2_SERVICING_EXECUTION_PAYMENT_LIFECYCLE_CONSUMPTION' OR contract_version<>1 OR schema_version<>'M2_8_SERVICING_EXECUTION_PAYMENT_LIFECYCLE_SCHEMA_V1' OR methodology_version<>'M2_8_METHOD_V1')))::text,'0',coalesce(((SELECT count(*)=0 FROM msbf_m2.application_servicing_execution_latest WHERE module1_run_id=(SELECT run_id FROM _m28_vctx) AND (contract_code<>'M2_SERVICING_EXECUTION_PAYMENT_LIFECYCLE_CONSUMPTION' OR contract_version<>1 OR schema_version<>'M2_8_SERVICING_EXECUTION_PAYMENT_LIFECYCLE_SCHEMA_V1' OR methodology_version<>'M2_8_METHOD_V1'))),FALSE),'Latest identity is exact.');
