    PERFORM pg_temp.m2_8_add_check('M2_8_POS_108_STRESS_NONIMPROVEMENT','STRESS_IMPROVEMENT_ROWS',((SELECT count(*) FROM msbf_m2.v_m2_8_matched_scenario_comparison WHERE module1_run_id=(SELECT run_id FROM _m28_vctx) AND (stress_processing_permission_improvement_flag OR stress_priority_improvement_flag OR stress_exposure_improvement_flag)))::text,'0',coalesce(((SELECT count(*)=0 FROM msbf_m2.v_m2_8_matched_scenario_comparison WHERE module1_run_id=(SELECT run_id FROM _m28_vctx) AND (stress_processing_permission_improvement_flag OR stress_priority_improvement_flag OR stress_exposure_improvement_flag))),FALSE),'Stress never improves processing, priority, or exposure.');
