    PERFORM pg_temp.m2_8_add_check('M2_8_POS_116_PAYMENT_SET_HASH','PAYMENT_SET_HASH',((SELECT payment_event_set_hash FROM msbf_ctl.m2_8_servicing_execution_contract_registry WHERE module1_run_id=(SELECT run_id FROM _m28_vctx)))::text,'32 lowercase hex',coalesce(((SELECT length(payment_event_set_hash)=32 AND payment_event_set_hash ~ '^[0-9a-f]+$' FROM msbf_ctl.m2_8_servicing_execution_contract_registry WHERE module1_run_id=(SELECT run_id FROM _m28_vctx))),FALSE),'PAYMENT_SET_HASH has valid shape.');
    PERFORM pg_temp.m2_8_add_check('M2_8_POS_117_REGISTRY_HASH','REGISTRY_HASH_ERRORS',((SELECT count(*) FROM msbf_ctl.m2_8_servicing_execution_contract_registry r WHERE r.module1_run_id=(SELECT run_id FROM _m28_vctx) AND r.row_hash IS DISTINCT FROM msbf_ctl.m2_8_registry_row_hash(to_jsonb(r))))::text,'0',coalesce(((SELECT count(*)=0 FROM msbf_ctl.m2_8_servicing_execution_contract_registry r WHERE r.module1_run_id=(SELECT run_id FROM _m28_vctx) AND r.row_hash IS DISTINCT FROM msbf_ctl.m2_8_registry_row_hash(to_jsonb(r)))),FALSE),'Registry hash reconstructs.');
