    PERFORM pg_temp.m2_8_add_check('M2_8_POS_120_ACCEPTANCE_NOT_WRITTEN','ACCEPTANCE_ROWS',((SELECT count(*) FROM msbf_ctl.acceptance_gate_result WHERE run_id=(SELECT run_id FROM _m28_vctx) AND gate_id='M2_8_SERVICING_EXECUTION_PAYMENT_LIFECYCLE_CONTROL'))::text,'0',coalesce(((SELECT count(*)=0 FROM msbf_ctl.acceptance_gate_result WHERE run_id=(SELECT run_id FROM _m28_vctx) AND gate_id='M2_8_SERVICING_EXECUTION_PAYMENT_LIFECYCLE_CONTROL')),FALSE),'Acceptance is not written early.');
END;$checks$;
DO $final$ DECLARE t bigint;p bigint;f bigint;BEGIN SELECT count(*),count(*) FILTER(WHERE status='PASS'),count(*) FILTER(WHERE status='FAIL') INTO t,p,f FROM _m28_validation;IF t<>120 THEN RAISE EXCEPTION 'M2.8 positive inventory failed: %.',t;END IF;
 INSERT INTO msbf_ctl.run_evidence(run_id,evidence_code,segment_key,metric_name,metric_value_numeric,metric_value_text,unit_code,status,interpretation)
 SELECT (SELECT run_id FROM _m28_vctx),evidence_code,'PORTFOLIO',metric_name,NULL,coalesce(observed_value,'<NULL>'),'VALIDATION',status,interpretation||' Threshold: '||coalesce(threshold_value,'<NULL>') FROM _m28_validation
 ON CONFLICT(run_id,evidence_code,segment_key) DO UPDATE SET metric_name=EXCLUDED.metric_name,metric_value_numeric=NULL,metric_value_text=EXCLUDED.metric_value_text,unit_code=EXCLUDED.unit_code,status=EXCLUDED.status,interpretation=EXCLUDED.interpretation,created_at=clock_timestamp();
 IF p=120 AND f=0 THEN UPDATE msbf_ctl.run_registry SET run_status='M2_8_VALIDATED' WHERE run_id=(SELECT run_id FROM _m28_vctx);UPDATE msbf_ctl.m2_8_servicing_execution_contract_registry SET contract_status='VALIDATED',validated_at=clock_timestamp() WHERE module1_run_id=(SELECT run_id FROM _m28_vctx);ELSE RAISE EXCEPTION 'M2.8 positive validation failed: pass %, fail %.',p,f;END IF;END;$final$;
COMMIT;SELECT * FROM _m28_validation ORDER BY evidence_code;
